mapper.select:
SET @start_comment_id = #{start_comment_id};
WITH RECURSIVE CommentHierarchy AS (
SELECT T.comment_id, T.parent_comment_id, T.comment_content, 0 AS level_depth, T.comment_id AS root_comment_id_tracker, T.parent_comment_id AS nearest_parent_id FROM board_comment_tb T WHERE T.comment_id = @start_comment_id
UNION ALL
SELECT T.comment_id, T.parent_comment_id, T.comment_content, CH.level_depth + 1 AS level_depth, T.comment_id AS root_comment_id_tracker, CH.nearest_parent_id FROM board_comment_tb T INNER JOIN CommentHierarchy CH ON T.comment_id = CH.parent_comment_id WHERE CH.parent_comment_id IS NOT NULL )
SELECT @start_comment_id AS start_comment_id, CH.nearest_parent_id, CH.comment_id AS root_comment_id, CH.level_depth FROM CommentHierarchy CH WHERE CH.parent_comment_id IS NULL LIMIT 1;
